		{
			if (player == localPlayer.get())
				clearLocalPlayer();
		}
		else if (dynamic_cast<Backpack*>(event.child.get()))
		{
			clearLocalBackpack();
		}
		else if (BackpackItem* item = dynamic_cast<BackpackItem*>(event.child.get()))
		{
			removeBackpackItem(item);
