			insertBackpackItem(item);
	}

	void LocalBackpack::onEvent(const Instance* source, DescendantRemoving event)
	{
		if (BackpackItem* item = dynamic_cast<BackpackItem*>(event.instance.get()))
			removeBackpackItem(item);
	}

